import fs from 'node:fs'
import path from 'node:path'
import { GAME_BALANCE } from '../src/game3d/config/gameBalance.js'
import { computeSeasonOutcome } from '../src/game3d/config/economy.js'

const STRATEGIES = ['burn', 'happy_seeder', 'bale_sell', 'mulch', 'compost']
const SEASONS = 10
const ACRES = 5

const lines = [
  '# 10-Season Economy Balance Report',
  '',
  'Generated by `scripts/balance-sim.js` using `src/data/scenarios.json` and `src/game3d/config/economy.js`.',
  ''
]

let allPassed = true

for (const strategy of STRATEGIES) {
  let state = { ...GAME_BALANCE.INITIAL_STATE, seasonIndex: 1, streak: 0 }
  let cappedBeforeS8 = false
  lines.push(`## Strategy: \`${strategy}\``)
  lines.push('| Season | Money (₹) | Soil | Village | Reputation | Net Season (₹) | Setback |')
  lines.push('| :---: | ---: | ---: | ---: | ---: | ---: | :--- |')

  for (let s = 1; s <= SEASONS; s++) {
    state.seasonIndex = s
    const outcome = computeSeasonOutcome(strategy, state, { acres: ACRES })
    state = {
      ...state,
      money: outcome.nextMoney,
      soilHealth: outcome.nextSoil,
      villageHealth: outcome.nextVillage,
      reputation: outcome.nextRep,
      streak: outcome.nextStreak
    }
    if (s < 8 && outcome.nextSoil >= 100 && outcome.nextVillage >= 100 && outcome.nextRep >= 100) {
      cappedBeforeS8 = true
    }
    lines.push(
      `| S${s} | ${outcome.nextMoney.toLocaleString('en-IN')} | ${outcome.nextSoil} | ${outcome.nextVillage} | ${outcome.nextRep} | ${outcome.netSeasonBalance.toLocaleString('en-IN')} | ${outcome.setback ? outcome.setback.label : 'None'} |`
    )
  }

  if (cappedBeforeS8) {
    allPassed = false
    lines.push('', `> ❌ Reached 100/100/100 before Season 8!`, '')
  } else {
    lines.push('', `> ✅ Balanced: did not cap 100/100/100 before Season 8.`, '')
  }
}

const outPath = path.resolve('docs/BALANCE_REPORT.md')
fs.writeFileSync(outPath, lines.join('\n'), 'utf8')
console.log(`Wrote ${outPath} (allPassed=${allPassed})`)
if (!allPassed) process.exit(1)
